scwin.gridView1_onheaderclick = function(headerId) {
    var value = gridView1.getHeaderValue(headerId);
    //alert("체크값 :  "+ value);
    log = value;
    var cnt = dataList1.getRowCount();
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id+'gridView1_column5')).children()[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "log", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
